import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    K = int(next(it))
    a = [int(next(it)) for _ in range(n)]
    best = None
    for l in range(n):
        seen = set()
        s = 0
        for r in range(l, n):
            if a[r] in seen:
                break
            seen.add(a[r])
            s += a[r]
            if s >= K:
                length = r - l + 1
                if best is None or length < best:
                    best = length
                break
    print(best if best is not None else -1)

if __name__ == "__main__":
    solve()
